      <div><span class="overline">عميلة من ${db.channels[c.channel]}</span><h1>${c.name}</h1><div class="chero__meta"><span>${I("phone", "ic--16")}<span class="ltr">${c.phone}</span></span><span>${I("map-pin", "ic--16")}${c.city}</span><span>${I("calendar", "ic--16")}آخر طلب ${c.lastAt ? db.fmtDate(c.lastAt) : "—"}</span></div><div class="chero__tags">${tagHtml(c)}</div></div>
